begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users limit 1),true);
do $$declare actor uuid=auth.uid();cid uuid=gen_random_uuid();co uuid=gen_random_uuid();sp uuid=gen_random_uuid();svc uuid=gen_random_uuid();site uuid=gen_random_uuid();d1 uuid=gen_random_uuid();d2 uuid=gen_random_uuid();veh uuid=gen_random_uuid();rid uuid=gen_random_uuid();rid2 uuid=gen_random_uuid();shift1 uuid;shift2 uuid;rec jsonb;stamp integer;token text;other_token text;trip uuid;resultid uuid=gen_random_uuid();batch uuid=gen_random_uuid();docs jsonb;original_start timestamptz;original_end timestamptz;begin
 if actor is null then raise exception 'TEST: fixture needs an auth user';end if;
 insert into respectlogistic_customers(id,owner_id,inn,payload) values(cid,actor,'9900000000','{"name":"DISPATCH-ROLLBACK","inn":"9900000000"}');
 insert into respectlogistic_contracts(id,owner_id,customer_id,kind,number,date,payload) values(co,actor,cid,'transport','DISPATCH-ROLLBACK-'||co,current_date,'{}');
 insert into respectlogistic_specifications(id,owner_id,customer_id,contract_id,number,date,payload) values(sp,actor,cid,co,'DISPATCH-SPEC-'||sp,current_date,'{}');
 insert into respectlogistic_services(id,owner_id,customer_id,contract_id,specification_id,name,unit,price_kopecks) values(svc,actor,cid,co,sp,'Перевозка','т',12200);
 insert into respectlogistic_sites(id,owner_id,customer_id,contract_id,specification_id,service_id,payload) values(site,actor,cid,co,sp,svc,'{"name":"TEST SITE","routeKm":"10"}');
 insert into crm_drivers(id,owner_id,app_scope,full_name) values(d1,actor,'respectlogistic','DISPATCH DRIVER'),(d2,actor,'respectlogistic','OTHER DRIVER');
 insert into crm_vehicles(id,owner_id,app_scope,plate,assigned_driver_id) values(veh,actor,'respectlogistic','D-'||substr(veh::text,1,8),d2);
 rec=jsonb_build_object('id',rid,'customer_id',cid,'site_id',site,'date_from',current_date,'date_to',current_date+7,'loading_address','LOAD','loading_point','55.7,37.6','unloading_point','Ворота 2','cargo_name','Песок','cargo_mass','По факту','unloading_address','UNLOAD','loading_from','08:00','loading_to','22:00','unloading_from','08:00','unloading_to','22:00','contact_name','TEST','contact_phone','+79990000000','time_zone','UTC');
 perform respectlogistic_save_dispatch(rec);
 if not exists(select 1 from respectlogistic_dispatch_requests where id=rid and payload->>'unloading_point'='Ворота 2' and payload->>'cargo_mass'='По факту' and payload->>'cargo_name'='Песок') then raise exception 'TEST: waybill fields not persisted';end if;
 if exists(select 1 from crm_trips where vehicle_id=veh) then raise exception 'TEST: draft created a trip';end if;
 perform respectlogistic_driver_access(d1,'password','dispatch-'||d1,'temporary-password-123');token=respectlogistic_driver_login('dispatch-'||d1,'temporary-password-123')->>'token';perform respectlogistic_driver_password(token,'permanent-password-456');
 perform respectlogistic_driver_access(d2,'password','dispatch-'||d2,'temporary-password-123');other_token=respectlogistic_driver_login('dispatch-'||d2,'temporary-password-123')->>'token';perform respectlogistic_driver_password(other_token,'permanent-password-456');
 perform respectlogistic_assign_dispatch(rid,1,current_date,current_date+1,jsonb_build_array(jsonb_build_object('vehicle_id',veh,'driver_id',d1)));
 perform respectlogistic_assign_dispatch(rid,1,current_date,current_date+1,jsonb_build_array(jsonb_build_object('vehicle_id',veh,'driver_id',d1)));
 if (select count(*) from respectlogistic_dispatch_shifts where request_id=rid)<>2 then raise exception 'TEST: assignment duplicated';end if;
 select id,version into shift1,stamp from respectlogistic_dispatch_shifts where request_id=rid and shift_date=current_date;
 select id into shift2 from respectlogistic_dispatch_shifts where request_id=rid and shift_date=current_date+1;
 perform respectlogistic_dispatch_action(shift1,stamp,'send');select version into stamp from respectlogistic_dispatch_shifts where id=shift1;
 perform set_config('request.jwt.claim.sub','',true);
 if jsonb_array_length(respectlogistic_driver_dispatch(other_token)->'dispatch_shifts')<>0 then raise exception 'TEST: other driver saw a shift';end if;
 if jsonb_array_length(respectlogistic_driver_dispatch(token)->'dispatch_shifts')<>1 or respectlogistic_driver_dispatch(token)::text like '%unit_price%' then raise exception 'TEST: shift missing or price leaked';end if;
 begin perform respectlogistic_driver_dispatch(other_token,'accept',shift1,stamp);raise exception using message='TEST: foreign driver accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_dispatch(token,'accept',shift1,stamp);
 if exists(select 1 from crm_trips where vehicle_id=veh) then raise exception 'TEST: acceptance created a trip/zero volume';end if;
 select starts_at,ends_at into original_start,original_end from respectlogistic_dispatch_shifts where id=shift1;
 update respectlogistic_dispatch_shifts set shift_date=current_date-1,starts_at=((current_date-1)+time '22:00') at time zone 'UTC',ends_at=(current_date+time '06:00') at time zone 'UTC' where id=shift1;
 if not exists(select 1 from jsonb_array_elements(respectlogistic_driver_dispatch(token)->'dispatch_vehicles') v where v->>'id'=veh::text) then raise exception 'TEST: overnight assigned vehicle unavailable on end day';end if;
 update respectlogistic_dispatch_shifts set shift_date=current_date,starts_at=original_start,ends_at=original_end where id=shift1;

 select version into stamp from respectlogistic_dispatch_shifts where id=shift1;
 begin perform respectlogistic_dispatch_result(shift1,jsonb_build_object('id',resultid,'volume',24.25,'unit','т'),stamp,token);raise exception using message='TEST: result without active duty',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_duty_action(token,veh,'start',0);
 trip=respectlogistic_dispatch_result(shift1,jsonb_build_object('id',resultid,'volume',24.25,'unit','т'),stamp,token);
 if respectlogistic_dispatch_result(shift1,jsonb_build_object('id',resultid,'volume',24.25,'unit','т'),stamp,token)<>trip then raise exception 'TEST: retry not idempotent';end if;
 begin perform respectlogistic_dispatch_result(shift1,jsonb_build_object('id',resultid,'volume',25,'unit','т'),stamp,token);raise exception using message='TEST: changed retry silently accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 if nullif(current_setting('request.jwt.claim.sub',true),'') is not null then raise exception 'TEST: owner identity leaked';end if;
 if not exists(select 1 from crm_trips where id=trip and app_scope='respectlogistic' and owner_id=actor and volume=24.25 and unit='т' and status='delivered' and not documents_confirmed) then raise exception 'TEST: trip fact incorrect';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 if to_regclass('public.rl_crm_payroll_accruals') is not null then
  execute 'select count(*) from public.rl_crm_payroll_accruals where trip_id=$1' into stamp using trip;
  if stamp<>1 then raise exception 'TEST: existing payroll ledger did not accrue exactly once';end if;
 end if;
 select version into stamp from respectlogistic_dispatch_requests where id=rid;
 perform respectlogistic_save_dispatch(rec||jsonb_build_object('date_to',current_date+14),stamp);
 if (select count(*) from respectlogistic_dispatch_shifts where request_id=rid)<>2 or (select status from respectlogistic_dispatch_shifts where id=shift1)<>'accepted' then raise exception 'TEST: extension duplicated/reset prior shifts';end if;
 perform respectlogistic_save_dispatch(rec||jsonb_build_object('id',rid2));
 begin perform respectlogistic_assign_dispatch(rid2,1,current_date,current_date,jsonb_build_array(jsonb_build_object('vehicle_id',veh,'driver_id',d1)));raise exception using message='TEST: double assignment accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 docs=respectlogistic_dispatch_documents(batch,array[shift1], '[{"kind":"ttn","count":2,"copies":3},{"kind":"waybill","count":1,"copies":1}]');
 if jsonb_array_length(docs)<>3 then raise exception 'TEST: document count wrong';end if;
 if respectlogistic_dispatch_documents(batch,array[shift1], '[{"kind":"ttn","count":2,"copies":3}]')<>docs then raise exception 'TEST: repeated print regenerated numbers';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 if jsonb_array_length(respectlogistic_read_dispatch()->'requests')<>0 then raise exception 'TEST: another owner read requests';end if;
 begin perform respectlogistic_save_dispatch(rec,2);raise exception using message='TEST: other owner edited request',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 select version into stamp from respectlogistic_dispatch_requests where id=rid;
 perform respectlogistic_save_dispatch(jsonb_build_object('id',rid),stamp,'cancel');
 if not exists(select 1 from crm_trips where id=trip and status='delivered') then raise exception 'TEST: cancellation deleted trip';end if;
 perform set_config('dispatch.test_request',rid::text,true);perform set_config('dispatch.test_token',token,true);
end$$;
-- A confirmed assignment can be replaced before work; only the replacement driver can report the trip.
do $$declare actor uuid=auth.uid();base respectlogistic_dispatch_requests;rid uuid=gen_random_uuid();old_driver uuid=gen_random_uuid();new_driver uuid;vehicle uuid=gen_random_uuid();old_shift uuid;new_shift uuid;stamp integer;old_token text;new_token text;trip uuid;docs jsonb;begin
 select * into base from respectlogistic_dispatch_requests where id=current_setting('dispatch.test_request')::uuid;
 select v.assigned_driver_id into new_driver from crm_vehicles v join respectlogistic_dispatch_shifts x on x.vehicle_id=v.id where x.request_id=base.id limit 1;
 insert into crm_drivers(id,owner_id,app_scope,full_name) values(old_driver,actor,'respectlogistic','REPLACED DRIVER');
 insert into crm_vehicles(id,owner_id,app_scope,plate,assigned_driver_id) values(vehicle,actor,'respectlogistic','R-'||substr(vehicle::text,1,8),old_driver);
 perform respectlogistic_driver_access(old_driver,'password','dispatch-'||old_driver,'temporary-password-123');old_token=respectlogistic_driver_login('dispatch-'||old_driver,'temporary-password-123')->>'token';perform respectlogistic_driver_password(old_token,'permanent-password-456');
 new_token=respectlogistic_driver_login('dispatch-'||new_driver,'permanent-password-456')->>'token';
 perform respectlogistic_save_dispatch(base.payload||jsonb_build_object('id',rid,'customer_id',base.customer_id,'site_id',base.site_id,'date_from',current_date,'date_to',current_date));
 perform respectlogistic_assign_dispatch(rid,1,current_date,current_date,jsonb_build_array(jsonb_build_object('vehicle_id',vehicle,'driver_id',old_driver)));
 select id,version into old_shift,stamp from respectlogistic_dispatch_shifts where request_id=rid;
 perform respectlogistic_dispatch_action(old_shift,stamp,'send');select version into stamp from respectlogistic_dispatch_shifts where id=old_shift;
 perform respectlogistic_driver_dispatch(old_token,'accept',old_shift,stamp);select version into stamp from respectlogistic_dispatch_shifts where id=old_shift;
 docs=respectlogistic_dispatch_documents(gen_random_uuid(),array[old_shift],'[{"kind":"waybill","count":1,"copies":1}]');
 perform respectlogistic_duty_action(old_token,vehicle,'start',0);
 begin perform respectlogistic_replace_dispatch_driver(old_shift,stamp,new_driver,'',true);raise exception using message='TEST: open driving period overwritten',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_duty_action(old_token,vehicle,'end',0);
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform respectlogistic_replace_dispatch_driver(old_shift,stamp,new_driver,'',true);raise exception using message='TEST: foreign owner replaced driver',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 begin perform respectlogistic_replace_dispatch_driver(old_shift,stamp-1,new_driver,'',true);raise exception using message='TEST: stale replacement accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 -- Sending must roll back the whole replacement if the chosen driver's access is blocked.
 perform respectlogistic_driver_access(new_driver,'block');
 begin perform respectlogistic_replace_dispatch_driver(old_shift,stamp,new_driver,'',true);raise exception using message='TEST: blocked driver received replacement',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 if (select status from respectlogistic_dispatch_shifts where id=old_shift)<>'accepted' then raise exception 'TEST: failed send cancelled original assignment';end if;
 perform respectlogistic_driver_access(new_driver,'unblock');new_token=respectlogistic_driver_login('dispatch-'||new_driver,'permanent-password-456')->>'token';
 new_shift=respectlogistic_replace_dispatch_driver(old_shift,stamp,new_driver,'',true);
 if (select status from respectlogistic_dispatch_shifts where id=old_shift)<>'cancelled' or not exists(select 1 from respectlogistic_dispatch_shifts where id=new_shift and driver_id=new_driver and status='sent') then raise exception 'TEST: replacement not atomic';end if;
 if exists(select 1 from crm_trips where vehicle_id=vehicle) then raise exception 'TEST: replacing created a fake trip';end if;
 if not exists(select 1 from respectlogistic_dispatch_documents where shift_id=old_shift and snapshot->>'driver_name'='REPLACED DRIVER') then raise exception 'TEST: historical document changed';end if;
 perform set_config('request.jwt.claim.sub','',true);
 select version into stamp from respectlogistic_dispatch_shifts where id=old_shift;
 begin perform respectlogistic_dispatch_result(old_shift,jsonb_build_object('id',gen_random_uuid(),'volume',12,'unit','т'),stamp,old_token);raise exception using message='TEST: cancelled driver reported a trip',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 select version into stamp from respectlogistic_dispatch_shifts where id=new_shift;
 begin perform respectlogistic_driver_dispatch(old_token,'accept',new_shift,stamp);raise exception using message='TEST: old driver accepted new assignment',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_dispatch(new_token,'accept',new_shift,stamp);select version into stamp from respectlogistic_dispatch_shifts where id=new_shift;
 perform respectlogistic_duty_action(new_token,vehicle,'start',0);
 trip=respectlogistic_dispatch_result(new_shift,jsonb_build_object('id',gen_random_uuid(),'volume',12,'unit','т'),stamp,new_token);
 if not exists(select 1 from crm_trips where id=trip and driver_id=new_driver and vehicle_id=vehicle) then raise exception 'TEST: trip used the old permanently assigned driver';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 begin perform respectlogistic_replace_dispatch_driver(new_shift,stamp,old_driver,'',false);raise exception using message='TEST: reported work reassigned',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 docs=respectlogistic_dispatch_documents(gen_random_uuid(),array[new_shift],'[{"kind":"waybill","count":1,"copies":1}]');
 if docs->0->'snapshot'->>'driver_name' is distinct from (select full_name from crm_drivers where id=new_driver) then raise exception 'TEST: new document used old driver';end if;
end$$;
set local role authenticated;
do $$begin
 if (select count(*) from public.respectlogistic_dispatch_requests where id=current_setting('dispatch.test_request')::uuid)<>1 then raise exception 'TEST: own RLS read failed';end if;
 begin update public.respectlogistic_dispatch_requests set version=99 where id=current_setting('dispatch.test_request')::uuid;raise exception using message='TEST: direct write accepted',errcode='P0002';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 if exists(select 1 from public.respectlogistic_dispatch_requests where id=current_setting('dispatch.test_request')::uuid) then raise exception 'TEST: other owner bypassed RLS';end if;
end$$;
set local role anon;
do $$begin
 begin perform respectlogistic_replace_dispatch_driver(null,1,null,'',false);raise exception using message='TEST: anon replacement RPC allowed',errcode='P0002';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform count(*) from public.respectlogistic_dispatch_requests;raise exception using message='TEST: anonymous table read accepted',errcode='P0002';exception when insufficient_privilege then null;end;
 if jsonb_array_length(public.respectlogistic_driver_dispatch(current_setting('dispatch.test_token'))->'dispatch_shifts')<>1 then raise exception 'TEST: opaque driver session failed as anon';end if;
 begin perform public.respectlogistic_driver_dispatch(repeat('b',64));raise exception using message='TEST: arbitrary token accepted',errcode='P0002';exception when sqlstate '28000' then null;end;
end$$;
reset role;
rollback;
select 'PASS: independent shifts, isolation, acceptance without fake volume, actual unload, conflict checks, idempotency, print snapshots, extension, safe driver replacement and actual trip driver. Rolled back.' as verification;
